namespace MTPR.Agent.Core.Models;

/// <summary>
/// Provider-independent completion returned by a language model.
/// </summary>
/// <param name="Content">Text generated by the model.</param>
/// <param name="FinishReason">Why the model stopped generating.</param>
/// <param name="Usage">Token usage, when the provider reports it.</param>
public sealed record LanguageModelResponse(
    string Content,
    FinishReason FinishReason,
    TokenUsage? Usage);
